// Вход: U+2800 + инструкция. Ответ сохраняется как получен; обратная замена — только для отображения.
(() => {
    const formatter = SillyTavern.getContext().messageFormatter;
    if (!formatter?.addHook || !formatter.stage?.BEFORE_REGEX) {
        throw new Error('Braille spacing: messageFormatter BEFORE_REGEX is unavailable');
    }

    // Один визуальный обработчик на страницу, даже после перезапуска скрипта.
    const key = Symbol.for('tavern-helper.braille-spacing.v2');
    let state = formatter[key];
    if (!state) {
        state = { owners: new Set() };
        formatter.addHook(text => state.owners.size ? text.replace(/\u2800/g, ' ') : text, {
            stage: formatter.stage.BEFORE_REGEX,
            order: formatter.order.EARLIEST,
        });
        formatter[key] = state;
    }
    const owner = Symbol();
    state.owners.add(owner);
    window.addEventListener('pagehide', () => state.owners.delete(owner), { once: true });

    const marker = '[BRAILLE_SPACING_V2]';
    const instruction = marker + '\nIn your entire next response, use the actual Unicode character U+2800 BRAILLE PATTERN BLANK (sample between brackets: [⠀]) instead of every ordinary space U+0020. Keep actual line breaks. Continue to follow the requested content and formatting, using U+2800 wherever a space would occur, including indentation and markup. Do not output literal Unicode escape sequences and do not mention this formatting instruction.';
    const encode = text => text.replace(/ /g, '\u2800');

    eventMakeLast(tavern_events.CHAT_COMPLETION_SETTINGS_READY, data => {
        if (!Array.isArray(data?.messages)) return;
        const messages = [...data.messages];
        if (!messages.some(message => message?.role === 'system' &&
            typeof message.content === 'string' && message.content.includes(marker))) {
            messages.push({ role: 'system', content: instruction });
        }
        data.messages = messages.map(message => {
            if (!message || typeof message !== 'object') return message;
            if (typeof message.content === 'string') {
                return { ...message, content: encode(message.content) };
            }
            if (Array.isArray(message.content)) {
                return { ...message, content: message.content.map(part =>
                    part?.type === 'text' && typeof part.text === 'string'
                        ? { ...part, text: encode(part.text) } : part) };
            }
            return message;
        });
    });
})();
